mapper.sql:
SELECT
file_id, file_name, file_extension, original_name, file_size, file_hash, mime_type, encoding,
storage_path, storage_type, bucket_name, owner_id, status, is_public, is_encrypted,
width, height, duration, version_number, is_latest_version, upload_ip, upload_user_agent,
upload_source, download_count, view_count, last_accessed_at, metadata, tags, description,
created_time
FROM file

    del_flag = '0'

        AND file_name LIKE CONCAT('%', #{param.fileName}, '%')


        AND file_extension = #{param.fileExtension}


        AND storage_type = #{param.storageType}


        AND status = #{param.status}


        AND is_public = #{param.isPublic}


        AND owner_id = #{param.ownerId}


        AND created_time >= #{param.startTime}


        AND created_time <= #{param.endTime}


ORDER BY created_time DESC
